"""Auto-generated section of data/LICENCES.md from the allowlist and the provenance log (rule 2).
Only the block between the markers is rewritten; the hand-written register above it is untouched."""
from __future__ import annotations

from collections import defaultdict

from ..common import path
from .core import allowlist, provenance

START = "<!-- AUTO:FETCHED START (generated by aidtrace_pipeline.fetch; do not edit by hand) -->"
END = "<!-- AUTO:FETCHED END -->"


def write_licences() -> str:
    by_src: dict[str, list[dict]] = defaultdict(list)
    for r in provenance():
        if r["event"] == "promoted":
            by_src[r["source"]].append(r)
    lines = [START, "", "## Fetched automatically from the approved allowlist", "",
             "| Source | Versions promoted | Latest version | Last accessed | Example URL | Licence (allowlist / provider) | Attribution |",
             "|---|---|---|---|---|---|---|"]
    for key, recs in sorted(by_src.items()):
        s = allowlist().get(key, {})
        last = max(recs, key=lambda r: r["at"])
        lic = s.get("licence", "UNVERIFIED")
        hdx = last.get("meta", {}).get("licence_hdx")
        if hdx:
            lic += f" / HDX: {hdx}"
        lines.append(f"| {s.get('name', key)} | {len({r['version'] for r in recs})} | {last['version']} | {last['accessed'][:10]} | "
                     f"{last['url'][:80]} | {lic} | {s.get('attribution', '')} |")
    lines += ["", "Full per-file provenance (URL, access time, version, size, SHA-256, check statistics): `data/provenance.jsonl`.",
              "Sources needing keys (IPC, IOM DTM API, GloFAS/CDS, HDX HAPI, ReliefWeb) and ACLED (written permission) are not fetched until configured.",
              "", END]
    block = "\n".join(lines)
    p = path("data/LICENCES.md")
    text = p.read_text(encoding="utf-8")
    if START in text and END in text:
        text = text[:text.index(START)] + block + text[text.index(END) + len(END):]
    else:
        text = text.rstrip() + "\n\n" + block + "\n"
    p.write_text(text, encoding="utf-8")
    return block
